BEGIN TRANSACTION;
CREATE TABLE chrono_inspections (
        inspection_id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id INTEGER NOT NULL,
        player_id INTEGER NOT NULL,
        replica_model TEXT NOT NULL,
        replica_type TEXT NOT NULL,
        measured_fps INTEGER NOT NULL,
        bb_weight_g REAL NOT NULL,
        calculated_joules REAL NOT NULL,
        passed BOOLEAN NOT NULL,
        retest_flag BOOLEAN NOT NULL DEFAULT 0,
        tested_at TIMESTAMP NOT NULL,
        FOREIGN KEY (session_id) REFERENCES gameday_sessions(session_id),
        FOREIGN KEY (player_id) REFERENCES players(player_id)
    );
CREATE TABLE clubs (
        club_id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        location TEXT NOT NULL,
        ukara_site_code TEXT NOT NULL
    );
CREATE TABLE gameday_sessions (
        session_id INTEGER PRIMARY KEY AUTOINCREMENT,
        club_id INTEGER NOT NULL,
        game_date DATE NOT NULL,
        weather TEXT,
        headcount INTEGER NOT NULL,
        chrono_tag_color TEXT NOT NULL,
        lead_marshal TEXT NOT NULL,
        FOREIGN KEY (club_id) REFERENCES clubs(club_id)
    );
CREATE TABLE player_registrations (
        registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id INTEGER NOT NULL,
        player_id INTEGER NOT NULL,
        waiver_signed BOOLEAN NOT NULL,
        armband_color TEXT NOT NULL,
        checked_in_at TIMESTAMP NOT NULL,
        FOREIGN KEY (session_id) REFERENCES gameday_sessions(session_id),
        FOREIGN KEY (player_id) REFERENCES players(player_id)
    );
CREATE TABLE players (
        player_id INTEGER PRIMARY KEY AUTOINCREMENT,
        callsign TEXT NOT NULL,
        first_name TEXT NOT NULL,
        last_name TEXT NOT NULL,
        email TEXT NOT NULL,
        phone TEXT NOT NULL,
        ukara_number TEXT,
        is_rental BOOLEAN NOT NULL DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE safety_incidents (
        incident_id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id INTEGER NOT NULL,
        player_id INTEGER NOT NULL,
        violation_type TEXT NOT NULL,
        escalation_level TEXT NOT NULL,
        notes TEXT,
        logged_at TIMESTAMP NOT NULL,
        FOREIGN KEY (session_id) REFERENCES gameday_sessions(session_id),
        FOREIGN KEY (player_id) REFERENCES players(player_id)
    );
DELETE FROM "sqlite_sequence";
COMMIT;
